import time
import json
import re

from burp import IBurpExtender
from burp import IHttpListener
from burp import IMessageEditorTab
from burp import IMessageEditorTabFactory

from java.io import PrintWriter

class BurpExtender(IBurpExtender, IHttpListener, IMessageEditorTabFactory):
    def registerExtenderCallbacks(self, callbacks):
        self._callbacks = callbacks
        self._helpers = callbacks.getHelpers()
        callbacks.setExtensionName("MarkINFO")
        self._stdout = PrintWriter(callbacks.getStdout(), True)
        callbacks.registerHttpListener(self)
        callbacks.registerMessageEditorTabFactory(self)
        print 'MarkINFO by [Vulkey_Chen]\nBlog: gh0st.cn\nTeam: MSTSEC'

    def createNewInstance(self, controller, editable):
        return MarkINFOTab(self, controller, editable)

    def processHttpMessage(self, toolFlag, messageIsRequest, messageInfo):
        if messageIsRequest:
            return
        content = messageInfo.getResponse()
        r = self._helpers.analyzeResponse(content)
        msg = content[r.getBodyOffset():].tostring()

        if isPhone(msg) or isIdCard(msg) or isEmail(msg):
            messageInfo.setHighlight('yellow')

        if (isPhone(msg) and isIdCard(msg)) or (isPhone(msg) and isEmail(msg)) or (isIdCard(msg) and isEmail(msg)):
            messageInfo.setHighlight('red')

class MarkINFOTab(IMessageEditorTab):
    def __init__(self, extender, controller, editable):
        self._extender = extender
        self._helpers = extender._helpers
        self._editable = editable
        self._txtInput = extender._callbacks.createTextEditor()
        self._txtInput.setEditable(editable)
        self.isInfo = False

    def getTabCaption(self):
        return "MarkINFO"

    def getUiComponent(self):
        return self._txtInput.getComponent()

    def isEnabled(self, content, isRequest):
        r = self._helpers.analyzeResponse(content)
        msg = content[r.getBodyOffset():].tostring()
        iphone = isPhone(msg)
        email = isEmail(msg)
        idcard = isIdCard(msg)
        if not isRequest:
            if iphone or email or idcard:
                return True

    def setMessage(self, content, isRequest):
        if content:
            if isRequest:
                r = self._helpers.analyzeRequest(content)
            else:
                r = self._helpers.analyzeResponse(content)
            msg = content[r.getBodyOffset():].tostring()
            info = ""
            iphone = isPhone(msg)
            email = isEmail(msg)
            idcard = isIdCard(msg)
            if iphone:
                info += '[Phone] ' + ','.join(iphone) + '\n'

            if email:
                info += '[Mail] ' + ','.join(email) + '\n'

            if idcard:
                info += '[IDCard] ' + ','.join(idcard) + '\n'

            self._txtInput.setText(info)
        else:
            return False

def isPhone(string):
    iphones = re.findall(r'((13[0-9]|14[5-9]|15[012356789]|166|17[0-8]|18[0-9]|19[8-9])[0-9]{8})', string)
    res = []
    if iphones != []:
        for i in iphones:
            lens = string.find(i[0])
            if (string[lens-1:lens].isdigit()) or (string[lens+11:lens+12].isdigit()):
                pass
            else:
                res.append(i[0])
        if res != []:
            return res
        else:
            return False
    else:
        return False

def isIdCard(string):
    coefficient = [7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2]
    parityBit = '10X98765432'
    idcards = re.findall(r'([1-9]\d{5}[1-9]\d{3}((0\d)|(1[0-2]))(([0|1|2]\d)|3[0-1])((\d{4})|\d{3}[xX]))', string)
    res = []
    if idcards != []:
        for idcard in idcards:
            sumnumber = 0
            for i in range(17):
                sumnumber += int(idcard[0][i]) * coefficient[i]
            if parityBit[sumnumber % 11] == idcard[0][-1]:
                res.append(idcard[0])
        if res != []:
            return res
        else:
            return False
    else:
        return False

def isEmail(string):
    emails = re.findall(r'[a-z0-9A-Z_]{1,19}@[0-9a-zA-Z]{1,13}\.[a-z]{1,6}', string)
    if emails != ['']:
        return emails
    else:
        return False

# you can write to stdout for debugging purposes, e.g.
# print("this is a debug message")

import math

def solution(A):

    # count the elements of A (by using dictionary)
    my_dictionary_1 = {}
    for item in A:
        if item not in my_dictionary_1:
            my_dictionary_1[item] = 1
        else:
            my_dictionary_1[item] += 1
    # print(my_dictionary_1)

    # count the number of non-divisors (into dictionary_2)
    my_dictionary_2 = {}
    for item in my_dictionary_1:
        num_divisor = 0
        item_sqrt = math.floor(math.sqrt(item))
        # print( str(item) + ' , ' + str(item_sqrt) )
        for i in range(1, item_sqrt+1, 1):
            if (item % i ==0):
                another_divisor = item / i 

                if i in my_dictionary_1:
                    num_divisor = num_divisor + my_dictionary_1[i] 

                if another_divisor != i:
                    if another_divisor in my_dictionary_1:
                        num_divisor = num_divisor + my_dictionary_1[another_divisor]

        num_non_divisor = len(A) - num_divisor
        my_dictionary_2[item] = num_non_divisor
    # print(my_dictionary_2)

    # put the number of non-divisors into an 'array' (by using list)
    array_non_divisor = []
    for i in range( len(A) ):
        array_non_divisor.append( my_dictionary_2[A[i]] )

    return array_non_divisor

# Code Written with routine coding tools-4
import os
from typing import Any


def generate_pydantic_model(schema: dict[str, Any], model_name: str, output_folder: str) -> None:
    os.makedirs(output_folder, exist_ok=True)

    code = generate_model_code(schema, model_name)

    with open(os.path.join(output_folder, f'{model_name}.py'), 'w') as f:
        f.write(code)


def generate_model_code(schema: dict[str, Any], model_name: str) -> str:
    code = 'from pydantic import BaseModel, Field\n'
    code += 'from typing import List, Dict, Optional\n\n'

    nested_classes, main_class = generate_class_code(schema, model_name)
    code += nested_classes + main_class

    return code


def generate_class_code(schema: dict[str, Any], model_name: str) -> str:
    nested_classes = ''
    main_class = f'class {model_name}(BaseModel):\n'

    for attr, attr_properties in schema.items():
        if 'type' not in attr_properties:
            continue

        if attr_properties['type'] == 'object':
            nested_model_name = f"{model_name}{attr.replace('_', ' ').title().replace(' ', '')}"
            nested_classes += generate_class_code(attr_properties['properties'], nested_model_name)[1]
            pydantic_type = nested_model_name
        else:
            pydantic_type = get_pydantic_type(attr_properties['type'])

        description = attr_properties.get('description', '')
        main_class += f'    {attr}: {pydantic_type} = Field(..., description={repr(description)})\n'

    main_class += '\n'
    main_class += '    def __str__(self) -> str:\n'
    main_class += '        return self.json(indent=4)\n\n'

    return nested_classes, main_class


def get_pydantic_type(json_type: str) -> str:
    type_mapping = {
        'string': 'str',
        'integer': 'int',
        'boolean': 'bool',
        'double': 'float',
        'map': 'Dict[str, Any]',
        'timestamp': 'str',
    }
    return type_mapping.get(json_type, 'str')


if __name__ == '__main__':
    # Sample JSON schema with nested dictionaries
    schema = {
        'name': {'description': 'The name of the person', 'type': 'string'},
        'age': {'description': 'The age of the person', 'type': 'integer'},
        'house_address': {
            'type': 'object',
            'properties': {
                'street': {'type': 'string', 'description': 'The street of the house address'},
                'city': {'type': 'string', 'description': 'The city of the house address'},
            },
        },
        'office_address': {
            'type': 'object',
            'properties': {
                'street': {'type': 'string', 'description': 'The street of the office address'},
                'city': {'type': 'string', 'description': 'The city of the office address'},
            },
        },
    }

    generate_pydantic_model(schema, 'Person', 'models')

#!/usr/bin/env python

# AWSBucketDump is a tool to quickly enumerate AWS S3 buckets to look for loot.
# It's similar to a subdomain bruteforcer but is made specifically to S3
# buckets and also has some extra features that allow you to grep for
# delicous files as well as download interesting files if you're not
# afraid to quickly fill up your hard drive.

# by Jordan Potti
# @ok_bye_now

from argparse import ArgumentParser
import requests
import xmltodict
import sys
import os
import shutil
import traceback
from queue import Queue
from threading import Thread, Lock


bucket_q = Queue()
download_q = Queue()

grep_list = None

arguments = None

def fetch(url):
    print('Fetching ' + url + '...')
    response = requests.get(url)
    if response.status_code == 403 or response.status_code == 404:
        status403(url)
    if response.status_code == 200:
        if "Content" in response.text:
            status200(response, grep_list, url)


def bucket_worker():
    while True:
        item = bucket_q.get()
        try:
            fetch(item)
        except Exception as e:
            traceback.print_exc(file=sys.stdout)
            print(e)
        bucket_q.task_done()

def downloadWorker():
    print('Download worker running...')
    while True:
        item = download_q.get()
        try:
            downloadFile(item)
        except Exception as e:
            traceback.print_exc(file=sys.stdout)
            print(e)
        download_q.task_done()

directory_lock = Lock()

def get_directory_lock():
    directory_lock.acquire()

def release_directory_lock():
    directory_lock.release()


def get_make_directory_return_filename_path(url):
    global arguments
    bits = url.split('/')
    directory = arguments.savedir
    for i in range(2,len(bits)-1):
        directory = os.path.join(directory, bits[i])
    try:
        get_directory_lock()
        if not os.path.isdir(directory):
            os.makedirs(directory)
    except Exception as e:
        traceback.print_exc(file=sys.stdout)
        print(e)
    finally:
        release_directory_lock()

    return os.path.join(directory, bits[-1]).rstrip()

interesting_file_lock = Lock()

def get_interesting_file_lock():
    interesting_file_lock.acquire()

def release_interesting_file_lock():
    interesting_file_lock.release()


def write_interesting_file(filepath):
    try:
        get_interesting_file_lock()
        with open('interesting_file.txt', 'ab+') as interesting_file:
            interesting_file.write(filepath.encode('utf-8'))
            interesting_file.write('\n'.encode('utf-8'))
    finally:
        release_interesting_file_lock()



def downloadFile(filename):
    global arguments
    print('Downloading {}'.format(filename) + '...')
    local_path = get_make_directory_return_filename_path(filename)
    local_filename = (filename.split('/')[-1]).rstrip()
    print('local {}'.format(local_path))
    if local_filename =="":
        print("Directory..\n")
    else:
        r = requests.get(filename.rstrip(), stream=True)
        if 'Content-Length' in r.headers:
            if int(r.headers['Content-Length']) > arguments.maxsize:
                print("This file is greater than the specified max size... skipping...\n")
            else:
                with open(local_path, 'wb') as f:
                    shutil.copyfileobj(r.raw, f)
        r.close()



def print_banner():
    print('''\nDescription:
    AWSBucketDump is a tool to quickly enumerate AWS S3 buckets to look for loot.
    It's similar to a subdomain bruteforcer but is made specifically to S3
    buckets and also has some extra features that allow you to grep for
    delicous files as well as download interesting files if you're not
    afraid to quickly fill up your hard drive.

    by Jordan Potti
    @ok_bye_now''')


def cleanUp():
    print("Cleaning up files...")

def status403(line):
    print(line.rstrip() + " is not accessible.")


def queue_up_download(filepath):
    download_q.put(filepath)
    print('Collectable: {}'.format(filepath))
    write_interesting_file(filepath)


def status200(response, grep_list, line):
    print("Pilfering "+line.rstrip() + '...')
    objects = xmltodict.parse(response.text)
    Keys = []
    try:
        contents = objects['ListBucketResult']['Contents']
        if not isinstance(contents, list):
            contents = [contents]
        for child in contents:
            Keys.append(child['Key'])
    except KeyError:
        pass
    for words in Keys:
        words = (str(words)).rstrip()
        collectable = line+'/'+words
        if grep_list is not None and len(grep_list) > 0:
            for grep_line in grep_list:
                grep_line = (str(grep_line)).rstrip()
                if grep_line in words:
                    queue_up_download(collectable)
                    break
        else:
            queue_up_download(collectable)

def main():
    global arguments
    global grep_list
    parser = ArgumentParser()
    parser.add_argument("-D", dest="download", required=False, action="store_true", default=False, help="Download files. This requires significant disk space.")
    parser.add_argument("-d", dest="savedir", required=False, default='', help="If -D, then -d 1 to create save directories for each bucket with results.")
    parser.add_argument("-l", dest="hostlist", required=True, help="") 
    parser.add_argument("-g", dest="grepwords", required=False, help="Provide a wordlist to grep for.")
    parser.add_argument("-m", dest="maxsize", type=int, required=False, default=1024, help="Maximum file size to download.")
    parser.add_argument("-t", dest="threads", type=int, required=False, default=1, help="Number of threads.")

    if len(sys.argv) == 1:
        print_banner()
        parser.error("No arguments given.")
        parser.print_usage()
        sys.exit()

    # output parsed arguments into a usable object
    arguments = parser.parse_args()

    # specify primary variables
    if arguments.grepwords:
        with open(arguments.grepwords, "r") as grep_file:
            grep_content = grep_file.readlines()
        grep_list = [g.strip() for g in grep_content]

    if arguments.download and arguments.savedir:
        print("Downloads enabled (-D), save directories (-d) for each host will be created/used.")
    elif arguments.download and not arguments.savedir:
        print("Downloads enabled (-D), will be saved to current directory.")
    else:
        print("Downloads were not enabled (-D), not saving results locally.")

    # start up bucket workers
    for _ in range(0, arguments.threads):
        print('Starting thread...')
        t = Thread(target=bucket_worker)
        t.daemon = True
        t.start()

    # start download workers
    for i in range(0, arguments.threads):
        t = Thread(target=downloadWorker)
        t.daemon = True
        t.start()

    with open(arguments.hostlist) as f:
        for line in f:
            bucket = 'http://'+line.rstrip()+'.s3.amazonaws.com'
            print('Queuing {}'.format(bucket) + '...')
            bucket_q.put(bucket)

    bucket_q.join()
    if arguments.download:
        download_q.join()

    cleanUp()

if __name__ == "__main__":
    main()

