@dispatcher.add_method
def create_raw_tx(vins, vouts):
    try:
        vins = json.loads(vins)
        vouts = json.loads(vouts)
        return Transaction.fromJSON({'vins': vins, 'vouts': vouts}).toJSON()

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def sign_raw_tx(tx: str, idx: int, pk: str):
    try:
        idx = int(idx)
        tx = Transaction.fromJSON(json.loads(tx))
        signed_tx = mutils.sign_tx(tx, idx, pk)
        return signed_tx.toJSON()

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def get_tx(txid: str):
    txid = str(txid)
    if txid in global_txs:
        return global_txs[txid].toJSON()
    return {'error': 'txid not found'}


@dispatcher.add_method
def send_raw_tx(tx: str):
    global global_best_block, global_txs, global_utxos

    try:
        # Original tx
        _tx_og = copy.deepcopy(tx)

        # Create new tx from the json dump
        tx = Transaction.fromJSON(json.loads(tx))

        # If is new tx then add it to block
        if tx.txid not in global_txs:
            # Add tx to global best block
            global_best_block, global_txs, global_utxos = mutils.add_tx_to_block(
                tx, global_best_block, global_txs, global_utxos
            )

            print('[INFO] txid {} added to block {}'.format(
                tx.txid, global_best_block.height))

            # Broadcast transaction to connected nodes
            for node in global_nodes:
                try:
                    misocoin_cli('send_raw_tx', [
                                 json.dumps(tx.toJSON())], **node)
                except Exception as e:
                    pass

        return {'txid': tx.txid}

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def receive_mined_block(block_str: str):
    global global_best_block, global_blockchain

    try:
        block: Block = Block.fromJSON(json.loads(block_str))
        add_to_blockchain(block)
        return {'success': True}

    except Exception as e:
        return {'error': str(e)}


@Request.application
def misocoin_app(request):
    response = JSONRPCResponseManager.handle(request.data, dispatcher)
    return Response(response.json, mimetype='application/json')


# Block management
# Handles the mining of blocks, as well as the automatic adjusting of difficulty
def block_management():
    global global_best_block, global_blockchain, global_txs, global_utxos, global_difficulty

    while True:
        time.sleep(10)

        try:
            last_mined_time = global_blockchain[-1].timestamp
        except:
            last_mined_time = genesis_epoch

        # Auto mine
        # if 30 seconds has passed since last mining
        if (time.time() - last_mined_time > 30):
            # Mine block
            mined_block = mine_block(global_best_block, account_address)

            if (mined_block.coinbase.reward_address == account_address):
                print('[SUCCESS] You found the nonce for block {}'.format(
                    mined_block.height))

            # Broadcast block to nodes
            mined_block_str = json.dumps(mined_block.toJSON())
            for node in global_nodes:
                # If node['host'] is in black list then continue
                if node['host'] in global_blacklisted_nodes:
                    continue

                try:
                    misocoin_cli('receive_mined_block', [
                                 mined_block_str], **node)

                except:
                    pass


@dispatcher.add_method
def init_connection(host, port):
    global global_nodes

    # Check if we already have the node,
    # add it if we dont
    has_node = reduce(lambda x, y: x and (
        y['host'] == host), global_nodes, False)
    if not has_node:
        global_nodes.append({'host': host, 'port': port})
    return json.dumps(global_nodes)


def sync_with_nodes():
    '''
    Syncs blocks with node
    '''
    global global_nodes

    # Init connection
    for node in global_nodes:
        try:
            misocoin_cli('init_connection', [global_host, global_port], **node)
        except:
            pass

    # Checks every 15 seconds
    while True:
        # Checks with nodes, syncs with the one with
        # the longest chain
        longest_node = None
        best_height = len(global_blockchain)

        for node in global_nodes:
            # If node['host'] is in black list then continue
            if node['host'] in global_blacklisted_nodes:
                continue

            try:
                node_best_length = misocoin_cli(
                    'get_info', [], **node)['height']

                if node_best_length > best_height:
                    longest_node = node
                    best_height = node_best_length

            except:
                pass

        # Syncs with that node
        if longest_node is not None:
            latest_block_dict: Dict = misocoin_cli(
                'get_block', [best_height], **longest_node)
            latest_block: Block = Block.fromJSON(latest_block_dict)

            # Append to latest blockchain
            add_to_blockchain(latest_block)

        time.sleep(10)


def run_misocoin(host='localhost', port=4000, nodes=['localhost:4000'], **kwargs):
    t1 = threading.Thread(target=partial(
        run_simple, threaded=True, request_handler=MisocoinRequestHandler), args=(host, port, misocoin_app))
    t1.daemon = True
    t1.start()

    t2 = threading.Thread(target=sync_with_nodes, args=())
    t2.start()

    t3 = threading.Thread(target=block_management, args=())
    t3.start()    

    t1.join()    
    t2.join()
    t3.join()


if __name__ == '__main__':
    config = list(filter(lambda x: x[0] is '-', sys.argv[1:]))
    config_kwargs = reduce(lambda x, y: {y.split(
        '=')[0][1:]: y.split('=')[1], **x}, config, {})

    # global host and port
    global_host = config_kwargs.get('host', global_host)
    global_port = config_kwargs.get('port', global_port)

    # Get global node and filter out useless values and
    # mush it into the format we want
    global_nodes = config_kwargs.get('nodes', '').split(',')
    global_nodes = list(
        filter(lambda x: (len(x) > 0 and ':' in x and x is not (global_host + ':' + str(global_port))), global_nodes))
    global_nodes = list(map(lambda x: {'host': x.split(
        ':')[0], 'port': x.split(':')[1]}, global_nodes))

    # account private key
    account_priv_key = config_kwargs.get('priv_key', get_new_priv_key())
    account_address = get_address(get_pub_key(account_priv_key))    

    print('** [Welcome] Your misocoin address is {}'.format(account_address))

    run_misocoin(**config_kwargs)

"""
Module for reading out CO2Meter USB devices
via a hidraw device under Linux
"""
import sys
import fcntl
import threading
import weakref

CO2METER_CO2 = 0x50
CO2METER_TEMP = 0x42
CO2METER_HUM = 0x41
HIDIOCSFEATURE_9 = 0xC0094806


def _co2_worker(weak_self):
    """
    Worker thread that constantly reads from the usb device.
    """
    while True:
        self = weak_self()
        if self is None:
            break
        self._read_data()

        if not self._running:
            break
        del self


class CO2Meter:
    _key = [0xc4, 0xc6, 0xc0, 0x92, 0x40, 0x23, 0xdc, 0x96]
    _device = ""
    _values = {}
    _file = ""
    _running = True
    _callback = None

    def __init__(self, device="/dev/hidraw0", callback=None):
        self._device = device
        self._callback = callback
        self._file = open(device, "a+b", 0)

        if sys.version_info >= (3,):
            set_report = [0] + self._key
            fcntl.ioctl(self._file, HIDIOCSFEATURE_9, bytearray(set_report))
        else:
            set_report_str = "\x00" + "".join(chr(e) for e in self._key)
            fcntl.ioctl(self._file, HIDIOCSFEATURE_9, set_report_str)

        thread = threading.Thread(target=_co2_worker, args=(weakref.ref(self),))
        thread.daemon = True
        thread.start()

    def _read_data(self):
        """
        Function that reads from the device, decodes it, validates the checksum
        and adds the data to the dict _values.
        Additionally calls the _callback if set
        """
        try:
            result = self._file.read(8)
            if sys.version_info >= (3,):
                data = list(result)
            else:
                data = list(ord(e) for e in result)

            if data[4] != 0x0d:
                """ newer devices don't encrypt the data, if byte 4!=0x0d assume encrypted data """
                data = self._decrypt(data)

            if data[4] != 0x0d or (sum(data[:3]) & 0xff) != data[3]:
                print(self._hd(data), "Checksum error")
                return

            operation = data[0]
            val = data[1] << 8 | data[2]
            self._values[operation] = self._convert_value(operation, val)
            if self._callback is not None:
                if operation in {CO2METER_CO2, CO2METER_TEMP} or (operation == CO2METER_HUM and val != 0):
                    self._callback(sensor=operation, value=val)
        except:
            self._running = False

    def _decrypt(self, data):
        """
        The received data has some weak crypto that needs to be decoded first
        """
        cstate = [0x48, 0x74, 0x65, 0x6D, 0x70, 0x39, 0x39, 0x65]
        shuffle = [2, 4, 0, 7, 1, 6, 5, 3]

        phase1 = [0] * 8
        for i, j in enumerate(shuffle):
            phase1[j] = data[i]

        phase2 = [0] * 8
        for i in range(8):
            phase2[i] = phase1[i] ^ self._key[i]

        phase3 = [0] * 8
        for i in range(8):
            phase3[i] = ((phase2[i] >> 3) | (phase2[(i - 1 + 8) % 8] << 5)) & 0xff

        ctmp = [0] * 8
        for i in range(8):
            ctmp[i] = ((cstate[i] >> 4) | (cstate[i] << 4)) & 0xff

        out = [0] * 8
        for i in range(8):
            out[i] = (0x100 + phase3[i] - ctmp[i]) & 0xff

        return out

    @staticmethod
    def _convert_value(sensor, value):
        """ Apply Conversion of value dending on sensor type """
        if sensor == CO2METER_TEMP:
            return round(value / 16.0 - 273.1, 1)
        if sensor == CO2METER_HUM:
            return round(value / 100.0, 1)

        return value

    @staticmethod
    def _hd(data):
        """ Helper function for printing the raw data """
        return " ".join("%02X" % e for e in data)

    def get_co2(self):
        """
        read the co2 value from _values
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_CO2 in self._values:
            result = {'co2': self._values[CO2METER_CO2]}

        return result

    def get_temperature(self):
        """
        reads the temperature from _values
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_TEMP in self._values:
            result = {'temperature': self._values[CO2METER_TEMP]}

        return result

    def get_humidity(self):  # not implemented by all devices
        """
        reads the humidty from _values.
        not all devices support this but might still return a value 0.
        So values of 0 are discarded.
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_HUM in self._values and self._values[CO2METER_HUM] != 0:
            result = {'humidity': self._values[CO2METER_HUM]}
        return result

    def get_data(self):
        """
        get all currently available values
        :returns dict with value or empty
        """
        result = {}
        result.update(self.get_co2())
        result.update(self.get_temperature())
        result.update(self.get_humidity())

        return result

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
An utility for combining various text files line by line. Useful for combining symbols (*.sym) files.

Python: 3.10+
License: MIT
Authors: EXL, MotoFan.Ru, GitHub Copilot (ChatGPT 4o)
Date: 27-Feb-2025
Version: 1.0

Usage:
	./combiner.py -o C390.sym -i C390_8.sym C390_16.sym C390_32.sym
"""

import argparse


def extract_func_name(sym_str: str) -> str:
	return sym_str.split()[-1]


# Produced with advanced coding tools.1 in GitHub Copilot: https://github.com/copilot/
def arrange_arrays(file_contents):
	# Step 1: Build master order based on first appearance.
	master_order = []
	seen = set()
	for file_content in file_contents:
		for sym_str in file_content:
			name = extract_func_name(sym_str)
			if name not in seen:
				master_order.append(name)
				seen.add(name)
	# Step 2: Build aligned arrays by master order.
	aligned_arrays = []
	for file_content in file_contents:
		sym_map = {extract_func_name(s): s for s in file_content}
		aligned = []
		for name in master_order:
			if name in sym_map:
				aligned.append(sym_map[name])
			else:
				aligned.append(f"# NOT_FOUND: T {name}")
		aligned_arrays.append(aligned)
	# Step 3: Sort all arrays by extract_func_name key, skipping the first line (ADS SYM header).
	for idx, arr in enumerate(aligned_arrays):
		if len(arr) > 1:
			header = arr[0]
			body = arr[1:]
			body_sorted = sorted(body, key=lambda s: extract_func_name(s).lower())
			aligned_arrays[idx] = [header] + body_sorted
	return aligned_arrays


def read_files(file_paths):
	file_contents = []
	for file_path in file_paths:
		with open(file_path, 'r') as f:
			file_contents.append(f.readlines())
	return file_contents


def combine_files(file_contents):
	combined_lines = []
	max_lines = max(len(contents) for contents in file_contents)

	for i in range(max_lines):
		lines_at_i = [contents[i].strip() if i < len(contents) else '' for contents in file_contents]
		if all(line == lines_at_i[0] for line in lines_at_i):
			combined_lines.append(lines_at_i[0])
		else:
			addresses = [line for line in lines_at_i if not line.startswith('# NOT_FOUND:')]
			if addresses:
				if all(addr.split()[0] == addresses[0].split()[0] for addr in addresses):
					print(f'OK   : {addresses}')
				else:
					print(f'FAIL : {addresses}')
				combined_lines.append(addresses[0])

	return combined_lines


def write_output(output_path, combined_lines):
	with open(output_path, 'w') as f:
		for line in combined_lines:
			f.write(line + '\n')


def main():
	parser = argparse.ArgumentParser(description='Concatenate text files line by line.')
	parser.add_argument('-o', '--output', required=True, help='Output file path')
	parser.add_argument('-i', '--input', required=True, nargs='+', help='Input file paths')

	args = parser.parse_args()

	file_contents = read_files(args.input)
	arranged_arrays = arrange_arrays(file_contents)
	combined_lines = combine_files(arranged_arrays)
	write_output(args.output, combined_lines)

if __name__ == '__main__':
	main()

