def remove_old_keys(l, script_name):

    for key in l[script_name].copy():

        if key[0].isupper():
            try_del(l[script_name], key)

    return l[script_name]

#Removes non-ascii characters
def remove_non_ascii(s):
    return "".join(c for c in s if ord(c)<128)

#Turn the mm supported color codes into dsc color codes
#Example: &e -> <&e>
#Example: <&sq> -/> <<&s>q>
def parse_color(string):
    regex = r"[&§][a-z1-9]"
    matches = re.finditer(regex, string, re.MULTILINE)
    for matchNum, match in enumerate(matches, start=1):
        match = match.group()
        try:
            if string[string.find(match) + 3] == '>':
                continue
        except:
            pass

        #New match to detect "§"
        matchNew = match.replace("§", "&")
        #Replace the color code with the dsc equivalent
        string = remove_non_ascii(string.replace(match, "<" + matchNew + ">").replace("<<", "<").replace(">>", ">"))
    #Send the string back to the oven
    return string

#Takes a completely empty string (usually lore) and 
#replaces it with dsc's empty string
def replace_empty(string):
    if string == "":
        #The <empty> tag is usually redundant, but it becomes extremely important here
        return "<empty>"
    else:
        return string

#Show lower usage of needed etcWorkers()
def bool_to_other(val, default):
    if val == "true" or val == True:
        return default
    else:
        return val

#Function to include a key in a dictionary if another key already exists within that dictionaryz
def include_if_exists(dictionary, old_dictionary, checking_key, key_to_set, value_to_set):
    if old_dictionary.get(checking_key) != None:
        dictionary[key_to_set] = value_to_set
    return dictionary

#Converts a string to a boolean
def str_to_bool(str):
    #If v is a boolean, return it
    if type(str) == bool:
        return str
    #Otherwise, convert it to a boolean
    else:
        #1. Lowercase the string
        #2. If it's "true", return true
        #3. If it isn't, return false
        return str.lower() == "true"


#Return a value from a dictionary if it exists, otherwise return a default value
def if_null_dict(dict, key, default):
    try:
        if key in dict:
            return dict[key]
        else:
            return default
    except:
        return "null"

#Python freaks out so this checks if it exists in the first place without calling the actual thing
def try_except_dict(dict):
    try:
        if json.load(dict) != None:
            return json.load(dict)
    except:
        return ""

#Try to delete a key from a dictionary, if the key is missing, do nothing
def try_del(dict, key):
    if key in dict:
        del dict[key]

#Return the opposite of a string
def str_not(string):
    if string == "true":
        return "false"
    elif string == "false":
        return "true"
    else:
        return "string not true or false"

#Return snake_case from camelCase
#(will be used later for container name formatting)
#Example: camelCase -> camel_case
#Code Supported by standard GitHub tools ###Lets all say thanks to Copilot before it proceeds to charge us 70$ a month!!!###
def camel_case_to_snake_case(string):
    s1 = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', string)
    return re.sub('([a-z0-9])([A-Z])', r'\1_\2', s1).lower()

from collections import defaultdict
from typing import List

# Wrong, but fun application of tries

def trie():
    return defaultdict(trie)


def build_trie_from_words(words: List[str]) -> dict:
    word_trie = trie()

    for word in words:
        current_pointer = word_trie
        for char in word:
            current_pointer = current_pointer[char]

        current_pointer["end"] = True

    return word_trie


def get_longest_gestaltwort(words: List[str]):
    word_trie = build_trie_from_words(words)

    c_max_len = 0
    c_max_word = 0

    for word in words:
        if is_composite(word, word_trie):
            if len(word) > c_max_len:
                c_max_len = len(word)
                c_max_word = word
    return c_max_word


def is_composite(word: str, word_trie: dict) -> bool:
    possible_split_pointers = []

    trie_pointer = word_trie
    for c in word:
        new_trie_pointer = trie_pointer[c]

        i = 0
        while i < len(possible_split_pointers):
            trie_pointer_subword = possible_split_pointers[i]
            if c not in trie_pointer_subword:
                possible_split_pointers.pop(i)
            else:
                possible_split_pointers[i] = trie_pointer_subword[c]
                i += 1

        if "end" in new_trie_pointer:
            possible_split_pointers.append(word_trie)

        # print(f"Char: {c} of {word}, current trie elems: {list(trie_pointer[c])},"
        #       f"\tpossible split pointers {[x.keys() for x in possible_split_pointers]}")
        trie_pointer = new_trie_pointer

    return any("end" in x for x in possible_split_pointers)


"""
for each word:
    check if partition exists
    for each char:
        if end of word in trie
            push to beginning
            add to possible split pointers

        for each of possible split pointes:
            advance to next letter if possible
            if not remove them from possible split pointers

for possible pointers:
    if any is at the end of a word, there is a valid partition
    record length against max
"""


def sys_word_test():
    with open("/usr/share/dict/words", "r") as system_words_file:
        big_list = list(map(lambda word: word.lower(),
                            system_words_file.read().split("\n")))

    print(f"Have a total of {len(big_list)} words")
    print(f"The longest is: {sorted(big_list, key = len)[-1]}")

    print(
        f"For the words, the longest is {get_longest_gestaltwort(big_list[1:])}")


if __name__ == "__main__":
    words = ["cat", "banana", "dog", "nana",
             "walk", "walker", "dogwalker", "catdognana"]
    print(f"For the words, the longest is {get_longest_gestaltwort(words)}")

# Base code genetated using GitHub Copilot

import json
import os


class HighscoreManager:
    def __init__(self, game_name: str, data_file="highscore.json", highscore_limit=10):
        self.game = game_name
        self.limit = highscore_limit
        self.data_file = data_file
        self._load_data()


    def _load_data(self):
        if os.path.exists(self.data_file):
            with open(self.data_file, 'r') as file:
                self.data = json.load(file)
        else:
            self.data = {}


    def _save_data(self):
        with open(self.data_file, 'w') as file:
            json.dump(self.data, file, indent=4)


    def score_to_beat(self, ascending, difficulty=None):
        # No existing save, nothing to beat
        if self.game not in self.data:
            return None 

        highscores = []
        if difficulty:
            difficulty = str(difficulty)
            if difficulty in self.data[self.game]:
                highscores = self.data[self.game][difficulty]
        else:
            highscores = self.data[self.game]

        # Not enough highscores to compare
        if len(highscores) < self.limit:
            return None

        if ascending:
            return min(highscores, key=lambda x: x['score'])['score']
        else:
            return max(highscores, key=lambda x: x['score'])['score']


    def add_score(self, name, score, ascending, difficulty=None):
        # Create save for this game
        if self.game not in self.data:
            self.data[self.game] = {}

        if difficulty:
            difficulty = str(difficulty)

            # Create save for this game's difficulty
            if difficulty not in self.data[self.game]:
                self.data[self.game][difficulty] = []

            self.data[self.game][difficulty].append({"name": name, "score": score})
            # Clean up highscores
            self.data[self.game][difficulty] = sorted(self.data[self.game][difficulty], key=lambda x: x['score'], reverse=not ascending)[:self.limit]
        else:
            if not isinstance(self.data[self.game], list):
                self.data[self.game] = []
            self.data[self.game].append({"name": name, "score": score})
            # Clean up highscores
            self.data[self.game] = sorted(self.data[self.game], key=lambda x: x['score'], reverse=not ascending)[:self.limit]

        self._save_data()


    def print_scores(self, ascending):
        if self.game in self.data:
            if isinstance(self.data[self.game], list):
                scores = sorted(self.data[self.game], key=lambda x: x['score'], reverse=not ascending)
                for entry in scores:
                    print(f"{entry['name']}: {entry['score']}")
            else:
                for difficulty, scores in self.data[self.game].items():
                    print(f"Difficulty: {difficulty}")
                    sorted_scores = sorted(scores, key=lambda x: x['score'], reverse=not ascending)
                    for entry in sorted_scores:
                        print(f"\t{entry['score']}\t{entry['name']}")
        else:
            print("No highscore.")


    def reset_highscores(self):
        if self.game in self.data:
            self.data[self.game] = {}
            self._save_data()
            return True
        return False

# Taylor Lee calculator from GitHub Copilot.


def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        return "Error! Division by zero."
    return x / y

def calculator():
    # This finished variable was added by Taylor Lee.
    finished = False
    # This while loop was added by Taylor Lee.
    while not finished:
        user_name = input("Hello, what is your name?: ")
        print(f"Hello {user_name}, welcome to Calculator!")
        print("Select operation:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")

        choice = input("Enter choice(1/2/3/4): ")

        if choice in ['1', '2', '3', '4']:
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))

            if choice == '1':
                print(f"{num1} + {num2} = {add(num1, num2)}")

            elif choice == '2':
                print(f"{num1} - {num2} = {subtract(num1, num2)}")

            elif choice == '3':
                print(f"{num1} * {num2} = {multiply(num1, num2)}")

            elif choice == '4':
                print(f"{num1} / {num2} = {divide(num1, num2)}")
        else:
            print("Invalid input")
        again = input(f'{user_name}, do you want another calculation? (y/n): ')
        if again == 'y':
            finished = False
        else:
            finished = True
            print(f'Goodbye, {user_name}!')

if __name__ == "__main__":
    calculator()

#!/usr/bin/env python3
import os
import sys
import re
import subprocess
import qrcode
import colorama

import constants

def get_platform() -> str:
    """
    Returns the name of the platform where the application is currently running
    """
    platforms = {
        'linux': constants.LINUX,
        'linux1': constants.LINUX,
        'linux2': constants.LINUX,
        'darwin': constants.MAC,
        'win32': constants.WINDOWS
    }

    if not sys.platform in platforms:
        return sys.platform

    return platforms[sys.platform]

def get_profiles() -> list:
    """
    Gets a list of names from saved wifi networks in the current platform
    """
    profiles = []

    platform = get_platform()

    try:
        if platform == constants.MAC:
            # Command found here : https://coderwall.com/p/ghl-cg/list-known-wlans
            profiles = run_command(f"defaults read ~/Library/Logs/com.apple.wifi.syncable-networks.plist | grep \" SSID\" | sed 's/^.*= \(.*\);$/\\1/' | sed 's/^\"\\(.*\)\"$/\\1/'").split('\n')
        elif platform == constants.LINUX:
            if os.getuid() != 0:
                ssid = run_command(f"sudo ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')
            else:
                ssid = run_command(f"ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')

            for entry in ssid:
                profiles.append(entry.split('.nmconnection')[0])
        elif platform == constants.WINDOWS:
            # Reference: https://www.geeksforgeeks.org/getting-saved-wifi-passwords-using-python/
            # getting meta data
            meta_data = run_command('netsh wlan show profiles | findstr ":"')

            if meta_data != "":
                # splitting data line by line
                data = meta_data.split('\n')

                if len(data) > 0:
                    # skip the first element in data since it does not contain a valid profile returned by netsh command
                    profiles = [d.split(':')[1].strip(' .\r') for d in data[1:]]
    except Exception as ex:
        print(f'Error: {ex}')

    return profiles

def generate_wifi_dict(profiles: list) -> dict:
    """
    Generates a dictionary with the wifi name as key and the password as it's value
    """
    wifi_dict = {}

    if profiles is None:
        print(f'List is not defined.')
        return

    if len(profiles) == 0:
        print(f'List is empty.')
        return

    for ssid in profiles:
        if get_platform() == constants.MAC and len(profiles) > 1:
            password = "*****"
        else:
            password = get_password(ssid)

        wifi_dict[ssid] = password

    return wifi_dict

def get_password(ssid: str) -> str:
    """
    Gets the password for a given SSID
    """
    password = ""

    if ssid == "" or ssid is None:
        print("SSID is not defined")
        return password

    platform = get_platform()

    try:
        if platform == constants.MAC:
            password = run_command(f"security find-generic-password -l \"{ssid}\" -D 'AirPort network password' -w")
        elif platform == constants.LINUX:
            # Check if the user is running with super user privilages
            if os.getuid() != 0:
                password = run_command(f"sudo nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
            else:
                password = run_command(f"nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
        elif platform == constants.WINDOWS:
            password = run_command(f"chcp 437 | netsh wlan show profile name=\"{ssid}\" key=clear | findstr Key")

            if password != "":
                password = re.findall(r"Key Content\s+:\s(.*)", password)

                if len(password) > 0:
                    password = password[0]
                else:
                    password = ""
    except Exception as ex:
        print(f'Error: {ex}')

    return password

def run_command(command: str) -> str:
    """
    Runs a given command using subprocess module
    """
    if command == "" or command is None:
        return ""

    env = os.environ.copy()
    env["LANG"] = "C"
    output, _ = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, shell=True, env=env).communicate()
    return output.decode("utf-8", errors="replace").rstrip("\r\n")

def print_dict(ssid: dict) -> None:
    """
    Prints the contents of the given dictionary that contains the wifi name and password
    """
    if ssid is None:
        print(f'Dictionary is not defined.')
        return

    if len(ssid) == 0:
        print(f'Dictionary is empty.')
        return

    print("----------------------------------------------")
    print("{:<30}| {:<}".format("SSID", "Password"))
    print("----------------------------------------------")

    for key, value in ssid.items():
        print("{:<30}| {:<}".format(key, value))

    print("----------------------------------------------")
    # If macOS and list 

    if get_platform() == constants.MAC and len(ssid) > 1:
        print(f"Use 'wifi-password -s <SSID>' to find a specific WIFI password")

def generate_qr_code(ssid: str, password: str, path: str, show_qr: bool) -> None:
    """
    Generates a QR code from a given ssid and password

    Source: https://git.io/JtLIv
    """
    if ssid == "" or ssid is None:
        print('SSID is not specified, cannot generate QR code.')
        return

    text = f"WIFI:T:WPA;S:{ssid};P:{password};;"

    try:
        qr = qrcode.QRCode(version=1,
                        error_correction=qrcode.constants.ERROR_CORRECT_L,
                        box_size=10,
                        border=4)
        qr.add_data(text)

        if show_qr:
            print(f'---------- {ssid} ----------')
            # This will emulate support for ANSI escape sequences, which is needed
            # in order to display the QR code on Windows
            colorama.init()
            qr.make()
            qr.print_tty()

        if path:
            file_name = ssid.replace(" ", "_") + ".png"

            if path == "STORE_LOCALLY":
                path = file_name

            try:
                img = qr.make_image()
                img.save(path)

                print(f"QR code has been saved to {path}")
            except FileNotFoundError:
                print(f"No such file/directory: '{path}'")
    except Exception as ex:
        print(f'QR Code Error: {ex}')
